#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    scanf("%d %d",&n,&m);
    vector<long long>a(n);
    for(int i=0;i<n;i++)scanf("%lld",&a[i]);
    long long lo=1, hi=*max_element(a.begin(),a.end()), ans=0;
    while(lo<=hi) {
        long long mid=(lo+hi)/2, cnt=0;
        for(auto x:a)cnt+=x/mid;
        if(cnt>=m) {
            ans=mid;
            lo=mid+1;
        }
        else hi=mid-1;
    }
    printf("%lld\n",ans);
    return 0;
}

