// 树状数组：单点修改 + 区间求和
typedef long long ll;
ll bit[300005];
int n;
void add(int i,ll v){ for(;i<=n;i+=i&-i) bit[i]+=v; }
ll pre(int i){ ll s=0; for(;i>0;i-=i&-i) s+=bit[i]; return s; }
int main() {
    int q;
    if(scanf("%d %d",&n,&q)!=2)return 0;
    for(int i=1;i<=n;i++) {
        ll v;
        scanf("%lld",&v);
        add(i,v);
    }
    while(q--) {
        int op,a,b;
        scanf("%d %d %d",&op,&a,&b);
        if(op==1) add(a,b);
        else printf("%lld\n",pre(b)-pre(a-1));
    }
    return 0;
}

