import sys
def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); q = int(data[1])
    bit = [0] * (n + 2)
    for i in range(1, n + 1):
        v = int(data[1 + i])
        j = i
        while j <= n:
            bit[j] += v
            j += j & -j
    out = []
    p = 2 + n
    for _ in range(q):
        op = int(data[p]); a = int(data[p + 1]); b = int(data[p + 2]); p += 3
        if op == 1:
            j = a
            while j <= n:
                bit[j] += b
                j += j & -j
        else:
            def pre(i):
                s = 0
                while i > 0:
                    s += bit[i]
                    i -= i & -i
                return s
            out.append(pre(b) - pre(a - 1))
    sys.stdout.write("".join(str(x) + "\n" for x in out))
main()

