int main() {
    int n, m;
    scanf("%d %d",&n,&m);
    vector<vector<int>>g(n+1);
    for(int i=0;i<m;i++) {
        int u, v;
        scanf("%d %d",&u,&v);
        g[u].push_back(v);
        g[v].push_back(u);
    }
    vector<int>vis(n+1,0);
    int c=0;
    for(int i=1;i<=n;i++) {
        if(vis[i])continue;
        c++;
        queue<int>q;
        q.push(i);
        vis[i]=1;
        while(!q.empty()) {
            int u=q.front();
            q.pop();
            for(int v:g[u])if(!vis[v]) {
                vis[v]=1;
                q.push(v);
            }
        }
    }
    printf("%d\n",c);
    return 0;
}

