int R, C, sx, sy, tx, ty;
vector<string>g;
int best=INT_MAX;
void dfs(int x,int y,int d) {
    if(d>=best)return;
    if(x==tx&&y==ty) {
        best=d;
        return;
    }
    int dx[4]={1, -1, 0, 0}, dy[4]={0, 0, 1, -1};
    g[x][y]='#';
    for(int k=0;k<4;k++) {
        int nx=x+dx[k], ny=y+dy[k];
        if(nx>=0&&nx<R&&ny>=0&&ny<C&&g[nx][ny]=='.')dfs(nx,ny,d+1);
    }
    g[x][y]='.';
}

int main() {
    scanf("%d %d",&R,&C);
    scanf("%d %d %d %d",&sx,&sy,&tx,&ty);
    g.resize(R);
    for(int i=0;i<R;i++) {
        char buf[1005];
        scanf("%s",buf);
        g[i]=buf;
    }
    dfs(sx,sy,0);
    printf("%d\n",best==INT_MAX?-1:best);
    return 0;
}

